const itemPattern = /^(?:(?<quantity>\d+)[ \t]*\u20ac[ \t]*x[ \t]*(?<unit_price>\d+,\d{2})[ \t]*)?(?<name>.+?)[ \t]+(?<total>-?\d+,\d{2})[ \t]*\*?[ \t]*(?<code>AW|A|B)$/;
const weightPattern = /^kg[ \t]+x[ \t]*(?<quantity>\d+,\d+)[ \t]+(?<unit_price>\d+,\d{2})(?:[ \t]*\u20ac[ \t]*\/[ \t]*kg)?$/i;
const discountPattern = /^App[ \t]+Preis[ \t]*\/[ \t]*Rabatt[ \t]+(?<total>-?\d+,\d{2})(?:[ \t]*\*?[ \t]*(?<code>AW|A|B))?$/i;
const unitPattern = /^\u20ac[ \t]*\/[ \t]*kg$/i;

function toMinor(value) {
  const [whole, fraction] = value.replace(/^-/, '').split(',');
  const amount = Number(whole) * 100 + Number(fraction);
  if (!Number.isSafeInteger(amount)) {
    throw new Error(`Money amount exceeds the supported range: ${value}`);
  }
  return value.startsWith('-') ? -amount : amount;
}

return $input.all().map((input, inputIndex) => {
  const products = [];
  const adjustments = [];
  const parseIssues = [];
  let rawText = '';
  let pendingWeight = null;
  let previousProduct = null;

  function issue(code, lineNumber, rawLine, reason) {
    parseIssues.push({ code, line_number: lineNumber, raw_line: rawLine, reason });
  }

  function discardPendingWeight(reason) {
    if (pendingWeight) {
      issue('unattached_weight', pendingWeight.line_number, pendingWeight.raw_line, reason);
      pendingWeight = null;
    }
  }

  function result() {
    return {
      json: {
        ...input.json,
        retailer_key: 'edeka',
        receipt_input_index: inputIndex,
        rawText,
        products,
        adjustments,
        parse_issues: parseIssues,
        review_required: parseIssues.length > 0,
      },
      pairedItem: { item: inputIndex },
    };
  }

  const text = input.json?.text;
  if (typeof text !== 'string' || !text.trim()) {
    issue('missing_text', 0, '', 'Expected a non-empty $json.text from Extract from File.');
    return result();
  }

  const normalizedText = text.replace(/\r\n?/g, '\n').replace(/[\u00a0\u202f]/g, ' ');
  const start = /\bEUR\b/.exec(normalizedText);
  const end = /\bPosten[ \t]*:/i.exec(normalizedText);
  if (!start || !end || end.index <= start.index) {
    issue('receipt_boundaries', 0, '', 'Could not locate the item section between EUR and Posten:.');
    return result();
  }

  rawText = normalizedText.slice(start.index + start[0].length, end.index).trim();
  if (!rawText) {
    issue('empty_item_section', 0, '', 'The receipt item section is empty.');
    return result();
  }

  for (const [index, rawLine] of rawText.split('\n').entries()) {
    const lineNumber = index + 1;
    const line = rawLine.trim();
    if (!line) continue;

    if (/^-{3,}$/.test(line)) {
      discardPendingWeight('A separator was encountered before a product.');
      previousProduct = null;
      continue;
    }

    if (unitPattern.test(line)) {
      if (!previousProduct || previousProduct.receipt_unit !== 'kg' || pendingWeight) {
        issue('unattached_unit', lineNumber, line, 'The EUR/kg label has no preceding weighted product.');
      }
      continue;
    }

    const weight = line.match(weightPattern);
    if (weight) {
      discardPendingWeight('Another weight line was encountered before a product.');
      const quantity = Number(weight.groups.quantity.replace(',', '.'));
      if (!Number.isFinite(quantity) || quantity <= 0) {
        issue('invalid_quantity', lineNumber, line, 'Weight must be a positive finite number.');
      }
      pendingWeight = {
        quantity,
        unit_price_minor: toMinor(weight.groups.unit_price),
        line_number: lineNumber,
        raw_line: line,
      };
      previousProduct = null;
      continue;
    }

    const discount = line.match(discountPattern);
    if (discount) {
      discardPendingWeight('A discount was encountered before a product.');
      const amount = toMinor(discount.groups.total);
      adjustments.push({
        line_number: lineNumber,
        raw_description: line,
        line_kind: 'discount',
        line_total_minor: amount,
        receipt_code: discount.groups.code ?? null,
        applies_to_line_number: previousProduct?.line_number ?? null,
      });
      if (!previousProduct || amount >= 0) {
        issue('unresolved_discount', lineNumber, line, 'Expected a negative discount immediately after a product.');
      } else {
        previousProduct.discount_total_minor += amount;
        previousProduct.net_line_total_minor += amount;
        if (previousProduct.net_line_total_minor < 0) {
          issue('negative_net_total', lineNumber, line, 'Discounts exceed the preceding product total.');
        }
      }
      continue;
    }

    const match = line.match(itemPattern);
    if (!match) {
      discardPendingWeight('An unrecognized line was encountered before a product.');
      issue('unrecognized_line', lineNumber, line, 'This line needs a parsing rule or manual review.');
      previousProduct = null;
      continue;
    }

    const { name, quantity, unit_price: unitPrice, total, code } = match.groups;
    const isDeposit = /^(?:Pfand\b|Leerg)/i.test(name);
    if (pendingWeight && (quantity !== undefined || isDeposit)) {
      issue('conflicting_quantity', lineNumber, line, 'A weight cannot be combined with a counted item or deposit.');
    }

    const receiptQuantity = pendingWeight?.quantity ?? Number(quantity ?? 1);
    const receiptUnit = pendingWeight ? 'kg' : 'item';
    const lineTotal = toMinor(total);
    const unitPriceMinor = pendingWeight?.unit_price_minor
      ?? (unitPrice === undefined ? lineTotal : toMinor(unitPrice));

    if (!Number.isSafeInteger(receiptQuantity) && !pendingWeight) {
      issue('invalid_quantity', lineNumber, line, 'Item count exceeds the supported integer range.');
    }
    if (!Number.isFinite(receiptQuantity) || receiptQuantity <= 0) {
      issue('invalid_quantity', lineNumber, line, 'Quantity must be a positive finite number.');
    }
    const calculatedTotal = Math.round(receiptQuantity * unitPriceMinor);
    if (!Number.isSafeInteger(calculatedTotal) || Math.abs(calculatedTotal - lineTotal) > 1) {
      issue('price_mismatch', lineNumber, line, 'Quantity multiplied by unit price differs from the printed total by more than one cent.');
    }

    const row = {
      retailer_key: 'edeka',
      receipt_input_index: inputIndex,
      ...(input.json.source_key === undefined ? {} : { source_key: input.json.source_key }),
      line_number: lineNumber,
      raw_description: line,
      product_name: name.trim(),
      normalized_description: name.normalize('NFKC').trim().replace(/\s+/g, ' ').toLowerCase(),
      line_kind: isDeposit ? 'deposit' : 'product',
      receipt_quantity: receiptQuantity,
      receipt_unit: receiptUnit,
      unit_price_minor: unitPriceMinor,
      line_total_minor: lineTotal,
      receipt_code: code,
    };
    pendingWeight = null;

    if (isDeposit) {
      adjustments.push(row);
      previousProduct = null;
    } else {
      if (lineTotal < 0) {
        issue('negative_product_total', lineNumber, line, 'Negative product lines need a return/cancellation rule, not a stock addition.');
      }
      row.discount_total_minor = 0;
      row.net_line_total_minor = lineTotal;
      products.push(row);
      previousProduct = row;
    }
  }

  discardPendingWeight('The item section ended before a product.');
  if (!products.length && !adjustments.length) {
    issue('no_recognized_items', 0, '', 'No products or adjustments were recognized.');
  }
  return result();
});

return $input.all().flatMap((input, index) => {
  const pdfs = Object.entries(input.binary ?? {}).filter(([, file]) =>
    file.mimeType?.toLowerCase() === 'application/pdf' || /\.pdf$/i.test(file.fileName ?? ''));
  if (!pdfs.length) throw new Error(`Message ${index} has no PDF receipt attachment.`);
  return pdfs.map(([key, file]) => ({
    json: { gmail_message_id: input.json.id, attachment_key: key, attachment_name: file.fileName ?? key },
    binary: { receipt_pdf: file },
    pairedItem: { item: index },
  }));
});

return $input.all().map((input, index) => ({
  json: { ...input.json, fingerprint_input: typeof input.json.text === 'string'
    ? input.json.text.normalize('NFKC').replace(/\s+/g, ' ').trim() : '' },
  pairedItem: { item: index },
}));

